import{_ as l,C as i,o as s,c as u,a2 as n,b as r,w as a,a as e,E as d,a3 as p}from"./chunks/framework.BC3NdntU.js";const q=JSON.parse('{"title":"4.1 网络分层模型","description":"","frontmatter":{},"headers":[],"relativePath":"卷四-网络与通信/4.1-网络分层模型.md","filePath":"卷四-网络与通信/4.1-网络分层模型.md","lastUpdated":1789367173000}'),h={name:"卷四-网络与通信/4.1-网络分层模型.md"};function g(c,t,b,E,A,C){const o=i("Mermaid");return s(),u("div",null,[t[3]||(t[3]=n('<h1 id="_4-1-网络分层模型" tabindex="-1">4.1 网络分层模型 <a class="header-anchor" href="#_4-1-网络分层模型" aria-label="Permalink to &quot;4.1 网络分层模型&quot;">​</a></h1><h2 id="引言-一次请求-数据要-过五关" tabindex="-1">引言:一次请求,数据要&quot;过五关&quot; <a class="header-anchor" href="#引言-一次请求-数据要-过五关" aria-label="Permalink to &quot;引言:一次请求,数据要&quot;过五关&quot;&quot;">​</a></h2><p>分层模型回答一个核心问题:<strong>数据从 A 出发,经过哪些层、每层干了什么,最后到 B</strong>。深挖要懂&quot;封装/解封装&quot;的 PDU 变化、DNS 解析、以及 TCP 的握手与可靠性机制。</p><hr><h2 id="一、两套模型-osi-七层-vs-tcp-ip-四层" tabindex="-1">一、两套模型:OSI 七层 vs TCP/IP 四层 <a class="header-anchor" href="#一、两套模型-osi-七层-vs-tcp-ip-四层" aria-label="Permalink to &quot;一、两套模型:OSI 七层 vs TCP/IP 四层&quot;">​</a></h2>',5)),(s(),r(p,null,{default:a(()=>[d(o,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E5%BA%94%E7%94%A8%E5%B1%82%20HTTP%2FDNS%5D%20--%3E%20B%5B%E4%BC%A0%E8%BE%93%E5%B1%82%20TCP%2FUDP%5D%0A%20%20%20%20B%20--%3E%20C%5B%E7%BD%91%E7%BB%9C%E5%B1%82%20IP%5D%0A%20%20%20%20C%20--%3E%20D%5B%E9%93%BE%E8%B7%AF%E5%B1%82%20MAC%5D%0A%20%20%20%20D%20--%3E%20E%5B%E7%89%A9%E7%90%86%E5%B1%82%20%E4%BF%A1%E5%8F%B7%5D%0A%20%20%20%20E%20--%3E%20F%5B%E5%AF%B9%E7%AB%AF%E5%8F%8D%E5%90%91%E8%A7%A3%E5%B0%81%E8%A3%85%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[e(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=n('<table tabindex="0"><thead><tr><th>OSI 七层</th><th>TCP/IP 四层</th><th>职责</th><th>协议</th></tr></thead><tbody><tr><td>应用/表示/会话</td><td>应用层</td><td>面向用户</td><td>HTTP、DNS、FTP</td></tr><tr><td>传输层</td><td>传输层</td><td>端到端、端口</td><td>TCP、UDP</td></tr><tr><td>网络层</td><td>网络层</td><td>寻址、路由</td><td>IP、ICMP</td></tr><tr><td>数据链路/物理</td><td>网络接口层</td><td>相邻传输、物理</td><td>以太网、MAC</td></tr></tbody></table><blockquote><p>OSI 是<strong>教学参考模型</strong>(七层,更细),TCP/IP 是<strong>实际工程模型</strong>(四层,互联网实际运行)。前者理论完备,后者务实精简。</p></blockquote><hr><h2 id="二、封装-解封装-每层的-数据单元-pdu" tabindex="-1">二、封装/解封装:每层的&quot;数据单元(PDU)&quot; <a class="header-anchor" href="#二、封装-解封装-每层的-数据单元-pdu" aria-label="Permalink to &quot;二、封装/解封装:每层的&quot;数据单元(PDU)&quot;&quot;">​</a></h2>',4)),(s(),r(p,null,{default:a(()=>[d(o,{id:"mermaid-99",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20A%5B%E5%BA%94%E7%94%A8%E5%B1%82%3A%E6%8A%A5%E6%96%87%20Message%5D%20--%3E%7C%E5%8A%A0%20TCP%20%E5%A4%B4%7C%20B%5B%E4%BC%A0%E8%BE%93%E5%B1%82%3A%E6%AE%B5%20Segment%5D%0A%20%20%20%20B%20--%3E%7C%E5%8A%A0%20IP%20%E5%A4%B4%7C%20C%5B%E7%BD%91%E7%BB%9C%E5%B1%82%3A%E5%8C%85%20Packet%5D%0A%20%20%20%20C%20--%3E%7C%E5%8A%A0%20MAC%20%E5%A4%B4%E5%B0%BE%7C%20D%5B%E9%93%BE%E8%B7%AF%E5%B1%82%3A%E5%B8%A7%20Frame%5D%0A%20%20%20%20D%20--%3E%7C%E8%BD%AC%E7%94%B5%E4%BF%A1%E5%8F%B7%7C%20E%5B%E7%89%A9%E7%90%86%E5%B1%82%3A%E6%AF%94%E7%89%B9%E6%B5%81%20Bits%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[e(" Loading... ",-1)])]),_:1})),t[5]||(t[5]=n(`<blockquote><p><strong>PDU 记忆</strong>:报文(Message)→ 段(Segment)→ 包(Packet)→ 帧(Frame)→ 比特(Bits)。每层只关心自己的头,不管别层内容——这就是&quot;封装&quot;。</p></blockquote><p><strong>一个具体例子(发&quot;你好&quot;)</strong>:应用层 HTTP 组织报文 → 传输层加端口/校验 → 网络层加 IP → 链路层加 MAC → 物理层转信号 → 对端逐层解封装还原。</p><hr><h2 id="三、各层关键概念" tabindex="-1">三、各层关键概念 <a class="header-anchor" href="#三、各层关键概念" aria-label="Permalink to &quot;三、各层关键概念&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>关键词</th><th>比方</th></tr></thead><tbody><tr><td>应用层</td><td>说什么</td><td>信的内容</td></tr><tr><td>传输层</td><td>怎么可靠送达(端口)</td><td>快递公司</td></tr><tr><td>网络层</td><td>送到哪(IP)</td><td>收件地址</td></tr><tr><td>链路层</td><td>下一跳给谁(MAC)</td><td>中转交接</td></tr></tbody></table><blockquote><p>IP 是&quot;地址&quot;(定位主机),MAC 是&quot;门牌&quot;(相邻设备),端口是&quot;收件的具体程序&quot;。</p></blockquote><hr><h2 id="四、为什么分层-底层价值" tabindex="-1">四、为什么分层(底层价值) <a class="header-anchor" href="#四、为什么分层-底层价值" aria-label="Permalink to &quot;四、为什么分层(底层价值)&quot;">​</a></h2><ol><li><strong>解耦</strong>:每层独立演进(HTTP/2 换不动 TCP)</li><li><strong>标准化</strong>:层间接口统一,互通</li><li><strong>可替换</strong>:网线换 WiFi,上层无感</li></ol><hr><h2 id="五、dns-解析流程-域名-→-ip" tabindex="-1">五、DNS 解析流程(域名 → IP) <a class="header-anchor" href="#五、dns-解析流程-域名-→-ip" aria-label="Permalink to &quot;五、DNS 解析流程(域名 → IP)&quot;">​</a></h2><p>浏览器先查<strong>本地缓存</strong>(浏览器缓存 → 系统 hosts → 路由器 → ISP),都没有则向 DNS 服务器<strong>递归 + 迭代</strong>查询:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 根域名服务器 → 返回 .com 顶级域名服务器地址</span></span>
<span class="line"><span>2. .com 服务器 → 返回 example.com 权威服务器地址</span></span>
<span class="line"><span>3. 权威服务器 → 返回真实 IP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>本地缓存逐层 → 根 → 顶级 → 权威。DNS 慢会拖慢首屏(可用 <code>preconnect</code>/<code>dns-prefetch</code> 提前解析,见 <a href="/frontend-knowledge-base/卷十-性能优化与工程质量/10.2-加载性能.html">10.2</a>)。</p></blockquote><hr><h2 id="六、tcp-三次握手与四次挥手" tabindex="-1">六、TCP:三次握手与四次挥手 <a class="header-anchor" href="#六、tcp-三次握手与四次挥手" aria-label="Permalink to &quot;六、TCP:三次握手与四次挥手&quot;">​</a></h2><h3 id="_6-1-三次握手-建立连接" tabindex="-1">6.1 三次握手(建立连接) <a class="header-anchor" href="#_6-1-三次握手-建立连接" aria-label="Permalink to &quot;6.1 三次握手(建立连接)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → SYN(seq=x)        → 服务器</span></span>
<span class="line"><span>客户端 ← SYN+ACK(seq=y, ack=x+1) ← 服务器</span></span>
<span class="line"><span>客户端 → ACK(ack=y+1)      → 服务器</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>为什么是三次不是两次?</strong> 两次握手下,<strong>失效的旧连接请求</strong>(网络延迟迟到)会让服务器<strong>白白建立连接、浪费资源</strong>;第三次 ACK 让双方都确认&quot;<strong>能收能发</strong>&quot;:客户端确认自己能发能收,服务器确认自己能发能收。</p><blockquote><p><strong>SYN 洪泛攻击</strong>:攻击者只发 SYN 不回复 ACK,服务器为半连接分配资源、队列被打满 → 无法服务正常请求。缓解:SYN Cookie(不占资源直到完成握手)。</p></blockquote><h3 id="_6-2-四次挥手-断开连接" tabindex="-1">6.2 四次挥手(断开连接) <a class="header-anchor" href="#_6-2-四次挥手-断开连接" aria-label="Permalink to &quot;6.2 四次挥手(断开连接)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 → FIN          → 服务器   (客户端:我不发了)</span></span>
<span class="line"><span>客户端 ← ACK          ← 服务器   (服务器:知道)</span></span>
<span class="line"><span>客户端 ← FIN          ← 服务器   (服务器:我也不发了)</span></span>
<span class="line"><span>客户端 → ACK          → 服务器   (客户端:好)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>为什么四次不是三次?</strong> TCP 是<strong>全双工</strong>,两个方向的连接要<strong>分别关闭</strong>:客户端 FIN 只表示&quot;我发完了&quot;,服务器可能还有数据要发,所以先 ACK、等发完再 FIN。方向独立 → 需要四个步骤。</p><p><strong>TIME_WAIT(主动关闭方):</strong> 主动断开的一方最后要等 <strong>2MSL</strong>(最长报文寿命 ×2),目的是:① 确保最后的 ACK 被对方收到(若丢失可重发);② 让旧连接的迟到报文在网络上&quot;自然消亡&quot;,不会污染新连接。</p><h3 id="_6-3-tcp-的可靠性机制" tabindex="-1">6.3 TCP 的可靠性机制 <a class="header-anchor" href="#_6-3-tcp-的可靠性机制" aria-label="Permalink to &quot;6.3 TCP 的可靠性机制&quot;">​</a></h3><p>TCP 的核心承诺:<strong>可靠、有序、不丢不重</strong>。靠这四样:</p><table tabindex="0"><thead><tr><th>机制</th><th>作用</th></tr></thead><tbody><tr><td><strong>序号 + 确认(ACK)</strong></td><td>每个字节编序号,收到回 ACK,知道谁到了谁没到</td></tr><tr><td><strong>超时重传</strong></td><td>超时未收到 ACK → 重发</td></tr><tr><td><strong>快速重传</strong></td><td>收到 3 个重复 ACK → 立即重传(不等超时)</td></tr><tr><td><strong>流量控制(滑动窗口)</strong></td><td>接收方通告窗口大小,发送方别发太快撑爆对方</td></tr><tr><td><strong>拥塞控制</strong></td><td>感知网络拥塞(慢启动 → 拥塞避免 → 快重传/快恢复),调节发送速率</td></tr></tbody></table>`,27)),(s(),r(p,null,{default:a(()=>[d(o,{id:"mermaid-298",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E6%85%A2%E5%90%AF%E5%8A%A8%3Cbr%2F%3E%E6%8C%87%E6%95%B0%E5%A2%9E%E9%95%BF%E7%AA%97%E5%8F%A3%5D%20--%3E%20B%5B%E6%8B%A5%E5%A1%9E%E9%81%BF%E5%85%8D%3Cbr%2F%3E%E7%BA%BF%E6%80%A7%E5%A2%9E%E9%95%BF%5D%0A%20%20%20%20B%20--%3E%20C%7B%E6%8B%A5%E5%A1%9E%3F%7D%0A%20%20%20%20C%20--%3E%7C%E8%B6%85%E6%97%B6%7C%20A%0A%20%20%20%20C%20--%3E%7C3%E4%B8%AA%E9%87%8D%E5%A4%8DACK%7C%20D%5B%E5%BF%AB%E9%87%8D%E4%BC%A0%2B%E5%BF%AB%E6%81%A2%E5%A4%8D%5D%0A%20%20%20%20D%20--%3E%20B%0A"})]),fallback:a(()=>[...t[2]||(t[2]=[e(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=n(`<blockquote><p><strong>流量控制 vs 拥塞控制</strong>:流量控制管&quot;<strong>接收方</strong>受不受得了&quot;(滑动窗口),拥塞控制管&quot;<strong>网络</strong>受不受得了&quot;(慢启动等)。一个对端、一个全局。</p></blockquote><hr><h2 id="七、tcp-vs-udp" tabindex="-1">七、TCP vs UDP <a class="header-anchor" href="#七、tcp-vs-udp" aria-label="Permalink to &quot;七、TCP vs UDP&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接</td><td>面向连接(三次握手)</td><td>无连接</td></tr><tr><td>可靠性</td><td>可靠(序号/重传/顺序)</td><td>不可靠</td></tr><tr><td>速度</td><td>慢(有握手和校验)</td><td>快</td></tr><tr><td>场景</td><td>HTTP、文件、邮件</td><td>视频通话、直播、DNS、游戏</td></tr></tbody></table><blockquote><p>取舍:<strong>TCP 用延迟/开销换可靠</strong>,适合&quot;必须完整正确&quot;;<strong>UDP 用可靠换快</strong>,适合&quot;丢一点无所谓但要实时&quot;。</p></blockquote><hr><h2 id="八、小结" tabindex="-1">八、小结 <a class="header-anchor" href="#八、小结" aria-label="Permalink to &quot;八、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分层:应用(HTTP/DNS)→ 传输(TCP/UDP,端口)→ 网络(IP,寻址)→ 链路/物理(MAC/信号)</span></span>
<span class="line"><span>封装/解封装:报文→段→包→帧→比特;每层只认自己的头</span></span>
<span class="line"><span>DNS:本地缓存 → 根 → 顶级 → 权威(递归+迭代)</span></span>
<span class="line"><span>TCP:三次握手(防失效连接+双向确认)、四次挥手(全双工分开关)、TIME_WAIT(2MSL)</span></span>
<span class="line"><span>可靠性:序号ACK + 重传 + 滑动窗口(流量控制)+ 拥塞控制</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="九、面试题" tabindex="-1">九、面试题 <a class="header-anchor" href="#九、面试题" aria-label="Permalink to &quot;九、面试题&quot;">​</a></h2><p><strong>Q1:TCP 和 UDP 的区别?</strong></p><p>TCP 面向连接(三次握手)、可靠(序号/重传/顺序)、慢;UDP 无连接、不可靠、快。TCP 用于 HTTP/文件,需&quot;完整正确&quot;;UDP 用于直播/DNS/游戏,需&quot;实时&quot;。</p><p><strong>Q2:什么是&quot;封装&quot;和&quot;解封装&quot;?</strong></p><p>封装:发送端<strong>每层加自己的头</strong>(应用→传输加 TCP 头→网络加 IP 头→链路加 MAC 头尾→物理转信号);解封装:接收端<strong>逐层拆头还原</strong>。各层只处理自己这层的协议。</p><p><strong>Q3:IP 地址和 MAC 地址的区别?</strong></p><p>IP 是<strong>网络层</strong>逻辑地址(定位主机、可变化);MAC 是<strong>链路层</strong>物理地址(硬件唯一、局域网内相邻传输用)。类比:IP 是&quot;收件地址&quot;,MAC 是&quot;门牌号&quot;,端口是&quot;收件人&quot;。</p><p><strong>Q4:为什么说前端主要关注&quot;应用层&quot;,但又要懂下面几层?</strong></p><p>前端直接打交道的是应用层(HTTP)。但&quot;断网仍能开页&quot;(缓存)、&quot;换 IP 后连接变化&quot;、TLS 握手、DNS 慢等性能/排查问题,都要到传输/网络层找原因。分层让&quot;上层能力、下层兜底&quot;。</p><p><strong>Q5:浏览器断网后为什么有时还能&quot;打开&quot;页面?</strong></p><p>因为命中<strong>浏览器 HTTP 缓存</strong>(应用层就返回了缓存),根本没走到传输/网络层。只有缓存未命中、需真网络请求时才因断网失败——&quot;上层能兜底就不麻烦下层&quot;。</p><p><strong>Q6:OSI 七层和 TCP/IP 四层的对应关系?</strong></p><p>OSI:应用/表示/会话 → TCP/IP 应用层;传输层 → 传输层;网络层 → 网络层;数据链路层/物理层 → 网络接口层。TCP/IP 是实际工程模型,OSI 是教学参考。</p><p><strong>Q7:为什么 TCP 握手要三次,挥手要四次?</strong></p><p>握手三次是为了<strong>防失效连接请求</strong> + 让双方确认&quot;能收能发&quot;;挥手四次是因为 TCP <strong>全双工</strong>,两个方向要<strong>分别关闭</strong>(客户端 FIN 后服务器可能还有数据要发,先 ACK 再 FIN),所以比握手多一步。</p><p><strong>Q8:TIME_WAIT 状态是什么?为什么主动关闭方要等 2MSL?</strong></p><p>主动断开方最后等 <strong>2MSL</strong>(最长报文寿命×2):① 确保最后的 ACK 被对方收到(丢失可重发);② 让旧连接迟到的报文在网络上<strong>自然消亡</strong>,不污染新连接。</p><p><strong>Q9:TCP 的流量控制和拥塞控制有什么区别?</strong></p><p><strong>流量控制</strong>:管&quot;接收方受不受得了&quot;,靠滑动窗口(接收方通告窗口大小);<strong>拥塞控制</strong>:管&quot;网络受不受得了&quot;,靠慢启动/拥塞避免/快重传/快恢复调节发送速率。一个对端、一个全局。</p><p><strong>Q10:浏览器输入 URL 到看到页面,发生了哪些网络层的步骤?</strong></p><p>DNS 解析(域名→IP)→ TCP 三次握手(或复用连接)→ TLS 握手(HTTPS)→ HTTP 请求/响应→ 渲染。DNS 慢、握手慢、网络往返(RTT)多都会拖慢首屏,所以有 preconnect/dns-prefetch/HTTP2 复用等优化。</p><hr><p>📎 参考:<a href="https://developer.mozilla.org/zh-CN/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work" target="_blank" rel="noreferrer">MDN《网络如何工作》</a>、<a href="https://developer.mozilla.org/zh-CN/docs/Glossary/DNS" target="_blank" rel="noreferrer">MDN《DNS》</a>、<a href="https://developer.mozilla.org/zh-CN/docs/Glossary/TCP_handshake" target="_blank" rel="noreferrer">MDN《TCP 握手》</a>、RFC 1122、RFC 1123</p>`,32))])}const T=l(h,[["render",g]]);export{q as __pageData,T as default};
